create table RB_CORP_NATURE_DEF (SEQ_NO VARCHAR(50) not null  ,ACCT_NATURE VARCHAR(10) null  ,REASON_CODE VARCHAR(10) null  ,ACCT_OPERATE_TYPE VARCHAR(10) null  ,TERM VARCHAR(5) null  ,TERM_TYPE VARCHAR(1) null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,ACCT_STATUS VARCHAR(1) null  ,COMPANY VARCHAR(20) null  ,RESTRAINT_TYPE VARCHAR(3) null  ,INLAND_OFFSHORE VARCHAR(1) null  ,CORPORATION VARCHAR(1) null  ,NATURE_PROPERTY VARCHAR(2) null  , primary key(SEQ_NO));